package com.eia.contract.expert.technicalaccount;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * Create payload for a technical account.
 *
 * <p>The account number is generated by the expert ({@code TA-{YEAR}-{SEQ}}) and
 * the balance is computed, so neither is accepted from the caller. Amounts are
 * decimal JSON values (a JSON number or a decimal string both deserialize to
 * {@link BigDecimal}); they must not be negative.</p>
 */
public record CreateTechnicalAccountRequest(
        LocalDate periodStart,
        LocalDate periodEnd,
        String currency,
        BigDecimal cededPremium,
        BigDecimal cededLosses,
        BigDecimal commission,
        BigDecimal otherCharges
) {}
